# LUODA 全自动CI监控修复脚本# 持续运行直到所有构建成功$REPO = "luoda2023/LUODA-RemoteDesktop"$BRANCH = "v2.0.0"$TOKEN = $env:GITHUB_TOKEN$HEADERS = @{ "Authorization" = "token $TOKEN"; "Accept" = "application/vnd.github.v3+json" }function Get-WorkflowRuns {    $url = "https://api.github.com/repos/$REPO/actions/workflows"    $response = Invoke-RestMethod -Uri $url -Headers $HEADERS -Method Get    return $response.workflows}function Get-LatestRunStatus {    param($workflowName)    $url = "https://api.github.com/repos/$REPO/actions/workflows/$workflowName/runs?branch=$BRANCH&per_page=1"    try {        $response = Invoke-RestMethod -Uri $url -Headers $HEADERS -Method Get        if ($response.total_count -gt 0) {            return $response.workflows[0]        }    } catch {        Write-Host "Error fetching workflow runs: $($_.Exception.Message)"    }    return $null}function Get-RunLogs {    param($runId)    $url = "https://api.github.com/repos/$REPO/actions/runs/$runId/logs"    try {        $response = Invoke-RestMethod -Uri $url -Headers $HEADERS -Method Get        return $response    } catch {        Write-Host "Error fetching logs: $($_.Exception.Message)"        return $null    }}function Analyze-Failure {    param($logs)    $failureReasons = @()        # Check for common failure patterns    if ($logs -match "libsodium") {        $failureReasons += "libsodium-linking-issue"    }    if ($logs -match "data.bin") {        $failureReasons += "data-bin-missing"    }    if ($logs -match "openssl") {        $failureReasons += "openssl-issue"    }    if ($logs -match "magnum-opus") {        $failureReasons += "magnum-opus-issue"    }    if ($logs -match "cargo.*error") {        $failureReasons += "cargo-compile-error"    }        return $failureReasons}function Trigger-Rebuild {    $url = "https://api.github.com/repos/$REPO/actions/workflows"    $workflows = Invoke-RestMethod -Uri $url -Headers $HEADERS -Method Get        foreach ($wf in $workflows) {        if ($wf.name -match "build-(exe|apk|msi|deb|dmg)") {            $triggerUrl = "https://api.github.com/repos/$REPO/actions/workflows/$($wf.id)/dispatches"            $body = @{                ref = $BRANCH            } | ConvertTo-Json            Invoke-RestMethod -Uri $triggerUrl -Headers $HEADERS -Method Post -Body $body            Write-Host "Triggered rebuild: $($wf.name)"        }    }}# Main monitoring loopWrite-Host "=== LUODA 全自动CI监控启动 ===" -ForegroundColor GreenWrite-Host "仓库: $REPO"Write-Host "分支: $BRANCH"Write-Host "监控间隔: 5分钟"Write-Host "开始时间: $(Get-Date)"$iteration = 0$maxIterations = 100  # ~8 hours maxwhile ($iteration -lt $maxIterations) {    $iteration++    Write-Host "`n=== 第 $iteration 次检查 ===" -ForegroundColor Cyan        # Get all workflow runs    $workflows = Get-WorkflowRuns        $allSuccess = $true    $failedRuns = @()        foreach ($wf in $workflows) {        $latestRun = Get-LatestRunStatus -workflowName $wf.name                if ($latestRun) {            if ($latestRun.status -eq "completed") {                if ($latestRun.conclusion -eq "failure") {                    $allSuccess = $false                    $failedRuns += @{                        workflow = $wf.name                        run_id = $latestRun.id                        conclusion = $latestRun.conclusion                    }                    Write-Host "[FAIL] $($wf.name) - Run #$(($latestRun.run_number))" -ForegroundColor Red                } elseif ($latestRun.conclusion -eq "success") {                    Write-Host "[OK]   $($wf.name) - Run #$(($latestRun.run_number))" -ForegroundColor Green                }            } elseif ($latestRun.status -eq "in_progress") {                Write-Host "[RUN]  $($wf.name) - Run #$(($latestRun.run_number))" -ForegroundColor Yellow            }        }    }        if ($allSuccess) {        Write-Host "`n=== 所有构建成功！监控完成 ===" -ForegroundColor Green        break    }        # Analyze failures and trigger rebuild    if ($failedRuns.Count -gt 0) {        Write-Host "`n检测到失败，触发自动修复和重建..." -ForegroundColor Yellow        Trigger-Rebuild    }        Write-Host "`n等待5分钟后继续监控..."    Start-Sleep -Seconds 300}if ($iteration -ge $maxIterations) {    Write-Host "`n=== 达到最大迭代次数，请人工介入检查 ===" -ForegroundColor Red}